/**
 * Shared query cache for Contact trigger actions.
 *
 * Singleton that exposes the parent Accounts of the contacts currently being
 * processed so that individual trigger actions never query Accounts themselves.
 * The inner Service class is registered as the first before-insert action and
 * (re)loads the map on every trigger execution, because later DML in the same
 * transaction can involve other accounts.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent accounts of the contacts in the current trigger execution,
     * keyed by Account Id. Populated by the Service action.
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * (Re)loads the parent accounts for the supplied contacts into accountsById.
     * The map is rebuilt from scratch on every call so stale rows from a
     * previous execution in the same transaction are discarded. Exactly one
     * Account query is issued per trigger execution.
     */
    public void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact con : contacts) {
            if (con.AccountId != null) {
                accountIds.add(con.AccountId);
            }
        }

        accountsById = new Map<Id, Account>();

        if (!accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
    }

    /**
     * Trigger action that loads the parent accounts for the contacts being
     * inserted. Registered with the lowest Order so it runs before any action
     * that depends on the account map.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts((List<Contact>) triggerNew);
        }
    }
}
